const domainToTopic: Record<string, TopicTag> = {
  'DDM & Profiles': 'DECLARATIVE_MANAGEMENT_DDM',
  'ADE & Enrollment': 'SUPERVISION_ADE',
  'APNs & Network': 'APNS_ARCHITECTURE',
  'Platform SSO & Identity': 'PLATFORM_SSO',
  'Jamf & AppConfig': 'JAMF_POLICIES',
  'Security & Updates': 'FILEVAULT_SECURITY',
};

export const EXAM_BANK: ExamQuestion[] = rawBank.map((q: any) => {
  const topicTag = domainToTopic[q.domain] || 'DECLARATIVE_MANAGEMENT_DDM';
  return {
    id: q.id,
    chapterId: q.chapterId || 1,
    topic: topicTag,
    domain: q.domain,
    qVn: q.q,
    qEn: q.en || q.q, // Bilingual text
    opts: q.opts,
    optsEn: q.optsEn || q.opts,
    ans: q.ans,
    expVn: q.exp,
    expEn: q.expEn || q.exp,
  };
});
